<?php
require_once __DIR__ . '/../database/app/layout.php';
$u=require_role(['admin']);$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$id=(int)($_POST['user_id']??0);$action=$_POST['action']??'';$reason=trim($_POST['reason']??'');
 if(!in_array($action,['verified','rejected','suspended'],true)){flash('Invalid action.','error');redirect('admin.php');}
 if($id===(int)$u['id']){flash('You cannot change your own verification status here.','error');redirect('admin.php');}
 $pdo->prepare("UPDATE users SET verification_status=?,is_active=? WHERE id=? AND role<>'admin'")->execute([$action,$action==='suspended'?0:1,$id]);
 $pdo->prepare("INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)")->execute([$u['id'],'user_'.$action,'users',$id,$reason?:null]);
 notify_user($id,'Account update','Your account status is now: '.$action.'.'.($reason?' Reason: '.$reason:''));flash('User status updated.','success');redirect('admin.php');
}
$pending=$pdo->query("SELECT id,name,email,phone,role,address,verification_status,created_at FROM users WHERE role<>'admin' AND verification_status='pending' ORDER BY created_at ASC")->fetchAll();
$flags=$pdo->query("SELECT sf.id,sf.food_name,sf.safety_deadline,sc.result,sc.checked_at,u.name AS donor FROM surplus_food sf JOIN users u ON u.id=sf.restaurant_id LEFT JOIN food_safety_checks sc ON sc.surplus_food_id=sf.id WHERE sf.safety_deadline<=NOW() OR sc.result='unsafe' OR sc.result='flagged' ORDER BY sf.safety_deadline ASC LIMIT 50")->fetchAll();
$summary=[];foreach(['users','surplus_food','demand_requests','donation_requests','deliveries'] as $t){$summary[$t]=(int)$pdo->query("SELECT COUNT(*) FROM `$t`")->fetchColumn();}
page_header('Admin control center');
?>
<div class="page-intro"><div class="eyebrow">ADMINISTRATION</div><h1>Control center <em>& oversight.</em></h1><p>Verify partners, review food safety, and monitor platform activity.</p></div>
<div class="dashboard-stats"><?php foreach(['users'=>'Users','surplus_food'=>'Food listings','demand_requests'=>'Demand requests','donation_requests'=>'Donation requests','deliveries'=>'Deliveries'] as $key=>$label): ?><div class="stat-card"><div class="stat-label"><?= e($label) ?></div><div class="stat-number"><?= number_format($summary[$key]) ?></div></div><?php endforeach; ?></div>
<section class="section"><div class="section-heading"><div><div class="eyebrow">REVIEW QUEUE</div><h2>Pending verification</h2></div></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Role</th><th>Contact</th><th>Address</th><th>Registered</th><th>Review</th></tr></thead><tbody><?php foreach($pending as $p): ?><tr><td><strong><?= e($p['name']) ?></strong><small class="table-sub"><?= e($p['email']) ?></small></td><td><?= e(ucwords(str_replace('_',' ',$p['role']))) ?></td><td><?= e($p['phone']) ?><small class="table-sub"><a href="<?= e(url('admin_document.php?id=' . (int)$p['id'])) ?>" target="_blank" rel="noopener">View document</a> · <a href="<?= e(url('admin_users.php')) ?>">Manage all users</a></small></td><td><?= e($p['address']) ?></td><td><?= e(date('d M Y',strtotime($p['created_at']))) ?></td><td><form method="post" class="inline-actions"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="user_id" value="<?= (int)$p['id'] ?>"><button class="btn btn-sm" name="action" value="verified">Verify</button><button class="btn btn-sm btn-danger" name="action" value="rejected">Reject</button></form></td></tr><?php endforeach; if(!$pending): ?><tr><td colspan="6" class="table-empty">No pending users.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="section"><div class="section-heading"><div><div class="eyebrow">SAFETY MONITORING</div><h2>Expired or flagged food</h2></div></div><div class="table-wrap"><table><thead><tr><th>Listing</th><th>Donor</th><th>Deadline</th><th>Safety result</th></tr></thead><tbody><?php foreach($flags as $f): ?><tr><td><?= e($f['food_name']) ?></td><td><?= e($f['donor']) ?></td><td><?= e(date('d M, g:i A',strtotime($f['safety_deadline']))) ?></td><td><?= status_badge($f['result']??'under_review') ?></td></tr><?php endforeach; if(!$flags): ?><tr><td colspan="4" class="table-empty">No expired or flagged listings currently found.</td></tr><?php endif; ?></tbody></table></div></section>
<?php page_footer(); ?>
